	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		SalesRegion
	 */
		public SalesRegion createSalesRegion( CreateSalesRegionCommand command ) {

		SalesRegion entity = new SalesRegion();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSalesRegionId( command.getSalesRegionId() );
            entity.setName( command.getName() );
            entity.setRegionCode( command.getRegionCode() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of SalesRegion {0} ", entity.toString() );

		return entity;
	}

